// WF-02: Detect Route
// Determines which sub-workflow to call based on user status + message type
// messageType from WF-01: 'text' or 'interactive'
// rawMessage.interactive.type: 'button_reply' (button tap) or 'nfm_reply' (flow form)

const input = $input.first().json;

const user = input.user || null;
const userStatus = user?.status || null;
const messageType = input.messageType || 'text';
const interactiveType = input.rawMessage?.interactive?.type || null;
const pendingUser = input.pendingUser || null;

let route;

// WhatsApp Flow form submission
if (messageType === 'interactive' && interactiveType === 'nfm_reply') {
  route = 'DETAILS_FORM';

// Post-consultation button tap (btn_feedback / btn_rebook) for consultation_closed users
} else if (messageType === 'interactive' && interactiveType === 'button_reply' && user !== null && userStatus === 'consultation_closed') {
  route = 'POST_CONSULT_TEXT';

// "Payment Completed" button tap — only valid for payment_pending users
} else if (messageType === 'interactive' && interactiveType === 'button_reply' && user !== null && userStatus === 'payment_pending') {
  route = 'PAYMENT_CONFIRM';

// No user record at all AND no pendingUser
} else if (user === null && pendingUser === null) {
  route = 'NEW_USER';

// pendingUser exists (received form, not yet submitted) — free text
} else if (user === null && pendingUser !== null) {
  route = 'PRE_FORM_TEXT';

// Text messages by status (user must be non-null for these branches)
} else if (user !== null && userStatus === 'payment_pending') {
  route = 'PAYMENT_PENDING_TEXT';

} else if (user !== null && userStatus === 'payment_submitted') {
  route = 'PAYMENT_SUBMITTED_TEXT';

} else if (user !== null && userStatus === 'consultation_active') {
  route = 'RELAY';

} else if (user !== null && userStatus === 'consultation_closed') {
  route = 'POST_CONSULT_TEXT';

} else {
  // Falls here for: orphan button_reply types (not payment_pending and not consultation_closed),
  // unexpected status values, blocked/opted_out (shouldn't reach here per WF-01 filter), etc.
  route = 'UNHANDLED';
}

return [{ json: { ...input, route } }];

const input = $input.first().json;
const phone = input.phoneNumber || '(unknown)';
const messageKind = input.messageType || 'unknown';
const interactiveType = input.rawMessage?.interactive?.type || null;
const userStatus = input.user?.status || 'not registered';
const onboardingInProgress = input.pendingUser ? 'yes' : 'no';
const content = (input.messageContent || '').slice(0, 200);

const lines = [
  `⚠️ The system couldn't route this message.`,
  `Phone: +${phone}`,
  `Message kind: ${messageKind}`,
];
if (interactiveType) lines.push(`Interactive type: ${interactiveType}`);
lines.push(`User status: ${userStatus}`);
lines.push(`Onboarding in progress: ${onboardingInProgress}`);
lines.push(`Content: ${content}`);
lines.push(`Please review.`);

return [{
  json: {
    channelId: 'C0A5B0ZE81E',
    messageText: lines.join('\n')
  }
}];

// WF-02 entry guard — design.md §2.1 + §2.7 WF-01 core envelope validation.
// Throws a descriptive error on any contract violation so the caller (WF-01)
// gets an immediate, named failure rather than a silent mis-route.
const i = $('When Executed by Another Workflow').item.json;

// ── Top-level required scalars ──────────────────────────────────────────────
if (!i.phoneNumber || typeof i.phoneNumber !== 'string')
  throw new Error('WF-02 contract: phoneNumber required (E.164 string), got: ' + JSON.stringify(i.phoneNumber));

if (!['text', 'interactive'].includes(i.messageType))
  throw new Error('WF-02 contract: messageType must be text|interactive, got: ' + JSON.stringify(i.messageType));

if (i.messageContent === undefined || i.messageContent === null)
  throw new Error('WF-02 contract: messageContent required (string or empty string), got: ' + JSON.stringify(i.messageContent));

// ── user object (null is valid — new-user path) ──────────────────────────────
if (i.user !== null && i.user !== undefined) {
  if (typeof i.user !== 'object' || Array.isArray(i.user))
    throw new Error('WF-02 contract: user must be null or an object, got: ' + typeof i.user);

  const u = i.user;

  if (u.id === undefined || u.id === null)
    throw new Error('WF-02 contract: user.id required (integer)');

  if (!u.phone_number || typeof u.phone_number !== 'string')
    throw new Error('WF-02 contract: user.phone_number required (E.164 string)');

  if (u.name === undefined || u.name === null)
    throw new Error('WF-02 contract: user.name required (string)');

  const validStatuses = ['payment_pending', 'payment_submitted', 'consultation_active', 'consultation_closed', 'blocked', 'opted_out'];
  if (!u.status || !validStatuses.includes(u.status))
    throw new Error('WF-02 contract: user.status must be a valid state-machine value, got: ' + JSON.stringify(u.status));

  if (!('slack_channel_id' in u))
    throw new Error('WF-02 contract: user.slack_channel_id key required (string or null)');

  if (!('current_consultation_id' in u))
    throw new Error('WF-02 contract: user.current_consultation_id key required (integer or null)');
} else if (i.user === undefined) {
  throw new Error('WF-02 contract: user key required (object or null), got: undefined');
}

// ── pendingUser (null is valid — not in-flight onboarding) ───────────────────
if (i.pendingUser !== null && i.pendingUser !== undefined) {
  if (typeof i.pendingUser !== 'object' || Array.isArray(i.pendingUser))
    throw new Error('WF-02 contract: pendingUser must be null or an object, got: ' + typeof i.pendingUser);
} else if (i.pendingUser === undefined) {
  throw new Error('WF-02 contract: pendingUser key required (object or null), got: undefined');
}

// Contract satisfied — pass through unchanged
return [{ json: i }];

